#!/bin/bash
# Prints the three IP addresses that appear most often in access.log,
# most frequent first. Ties are broken by first appearance in the log.
set -euo pipefail

LOG_FILE="$(dirname "$0")/access.log"

awk '{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        printf "%d %d %s\n", count[ip], i, ip
    }
}' "$LOG_FILE" | sort -k1,1nr -k2,2n | head -n 3 | awk '{print $3}'
